      ('Sovvan',        'Procurement-02',            'procurement',   'L6', 'sovvan@dcos.com',       'Anna',     'male',  '2019-04-28'::date),
      ('Seyha',         'MEP Senior',                'mep',           'L5', 'seyha@dcos.com',        'Hanko',    'male',  '2019-06-09'::date),
