      ('Sokun',         'Site Engineer - Architect', 'construction',  'L6', 'sokun@dcos.com',        'Ratanak',  'male',  '2022-06-27'::date),
      ('Dany',          'Architectural Design-01',   'architecture',  'L6', 'dany@dcos.com',         'Pheara',   'male',  '2022-07-18'::date),
      ('Nita',          'MEP Design',                'mep',           'L6', 'nita@dcos.com',         'Seyha',    'female','2023-01-03'::date),
