      ('Kimseng',       'HR Manager',                'hr',            'L4', 'kimseng@dcos.com',      'Sophat',   'male',  '2026-01-28'::date),
      ('Thida',         'Architectural Design-02',   'architecture',  'L6', 'thida@dcos.com',        'Pheara',   'female','2026-04-11'::date),
      ('Kimly',         'HR-02',                     'hr',            'L6', 'kimly@dcos.com',        'Pepsi',    'female','2026-04-12'::date),
